----------------------------------------------------------------------------------------
---- KEYBINDINGS (STRICT LUA FIX) -----------------------------------------------------
----------------------------------------------------------------------------------------

local mainMod = "SUPER"

-- ───────── Мышиные события (Mouse Binds) ─────────
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag,   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize, { mouse = true })

-- ───────── Основные действия с окнами ─────────
-- ИСПРАВЛЕНИЕ: Добавлен пустой объект параметров для закрытия окон
hl.bind(mainMod .. " + C",         hl.dsp.window.close({})) 
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + F",         hl.dsp.window.fullscreen({ mode = 0 }))

-- Перемещение окон (Move Window)
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ direction = "left" }),  { repeating = true })
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ direction = "right" }), { repeating = true })
hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.window.move({ direction = "up" }),    { repeating = true })
hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.window.move({ direction = "down" }),  { repeating = true })

-- Изменение размера окон (Resize Active)
hl.bind(mainMod .. " + CTRL + left",  hl.dsp.window.resize({ x = -200, y = 0, relative = true }))
hl.bind(mainMod .. " + CTRL + right", hl.dsp.window.resize({ x = 200, y = 0, relative = true }))
hl.bind(mainMod .. " + CTRL + up",    hl.dsp.window.resize({ x = 0, y = -200, relative = true }))
hl.bind(mainMod .. " + CTRL + down",  hl.dsp.window.resize({ x = 0, y = 200, relative = true }))

-- Переключение фокуса (Focus)
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- ───────── Запуск приложений и IPC Noctalia v5 ─────────
hl.bind("CTRL + ALT + T", hl.dsp.exec_cmd("kitty"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd("nautilus"))

-- ИСПРАВЛЕНИЕ: Нативные вызовы переключателей модулей Noctalia v5 через exec_cmd
hl.bind(mainMod .. " + R", function() hl.exec_cmd("noctalia msg panel-toggle launcher") end)
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd("noctalia toggle clipboard"))
hl.bind(mainMod .. " + P",         hl.dsp.exec_cmd("noctalia toggle control-center"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.exec_cmd("noctalia toggle settings"))
hl.bind(mainMod .. " + Q",         hl.dsp.exec_cmd("noctalia toggle media"))
hl.bind(mainMod .. " + B",         hl.dsp.exec_cmd("noctalia toggle power"))
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd("noctalia toggle wallpaper"))
hl.bind(mainMod .. " + S",         hl.dsp.exec_cmd("noctalia toggle calendar"))
hl.bind(mainMod .. " + N",         hl.dsp.exec_cmd("noctalia toggle network"))
hl.bind(mainMod .. " + V",         hl.dsp.exec_cmd("noctalia toggle volume"))
hl.bind(mainMod .. " + H",         hl.dsp.exec_cmd("noctalia toggle guide"))

-- Скриншоты и системные утилиты
hl.bind("Print",                 hl.dsp.exec_cmd("~/.config/hypr/scripts/screenshot.sh"),          { locked = true })
hl.bind("SHIFT + Print",         hl.dsp.exec_cmd("~/.config/hypr/scripts/screenshot.sh --edit"),   { locked = true })
hl.bind(mainMod .. " + Print",         hl.dsp.exec_cmd("~/.config/hypr/scripts/screenshot.sh --full"),   { locked = true })
hl.bind(mainMod .. " + SHIFT + Print", hl.dsp.exec_cmd("~/.config/hypr/scripts/screenshot.sh --full --edit"), { locked = true })

-- Блокировка экрана и Управление медиаплеером
hl.bind("XF86PowerOff",   hl.dsp.exec_cmd("bash ~/.config/hypr/scripts/lock.sh"), { locked = true })
hl.bind(mainMod .. " + L",      hl.dsp.exec_cmd("bash ~/.config/hypr/scripts/lock.sh"), { locked = true, repeating = true })
hl.bind(mainMod .. " + SPACE",  hl.dsp.exec_cmd("playerctl play-pause"),                { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"),                { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"),                { locked = true })

-- Мультимедиа клавиши (Громкость и Яркость)
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),   { locked = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true })
hl.bind("Caps_Lock",            hl.dsp.exec_cmd("sleep 0.1"),                                      { locked = true })

-- Циклический перебор активных мониторов
hl.bind(mainMod .. " + TAB", hl.dsp.exec_cmd("~/.config/hypr/scripts/focus_next_monitor.sh"))

-- ───────── Рабочие столы (Workspaces 1-10) ─────────
for i = 1, 10 do
    local key = i % 10
    hl.bind(mainMod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end


