----------------------------------------------------------------------------------------
---- WINDOW & LAYER RULES (NATIVE LUA SYNTAX) ------------------------------------------
----------------------------------------------------------------------------------------

-- Игнорирование запросов на максимизацию от приложений
local suppressMaximizeRule = hl.window_rule({
    name  = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

-- Исправление проблем с перетаскиванием в XWayland
hl.window_rule({
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },
    no_focus = true,
})

-- Фикс позиции для утилиты hyprland-run
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },
    move  = "20 monitor_h-120",
    float = true,
})

-- ───────── Правила для окон (Window Rules) ─────────

-- Настройки для встроенного меню приложений (App Launcher) Noctalia v5
hl.window_rule({
    name  = "noctalia-launcher",
    match = { title = "^(app-launcher)$" },
    float = true,
    center = true,
    size  = "1200 600",
    animation = "slide",
})

-- Настройка прозрачности для терминала Kitty (0.85 override)
hl.window_rule({
    name  = "kitty-opacity",
    match = { class = "^(kitty)$" },
    opacity = "0.85 override 0.85 override",
})

-- ───────── Правила для слоев (Layer Rules) ─────────

-- Отключаем анимацию для всплывающих OSD индикаторов Noctalia и системы
hl.layer_rule({
    name  = "no-anim-volume-osd",
    match = { namespace = "^(volume_osd)$" },
    no_anim = true,
})

hl.layer_rule({
    name  = "no-anim-brightness-osd",
    match = { namespace = "^(brightness_osd)$" },
    no_anim = true,
})

-- Отключаем анимацию для утилиты выбора цвета hyprpicker
hl.layer_rule({
    name  = "no-anim-hyprpicker",
    match = { namespace = "hyprpicker" },
    no_anim = true,
})

-- Включаем размытие фона и прозрачность для экрана блокировки (ext-session-lock)
hl.layer_rule({
    name  = "blur-lockscreen",
    match = { namespace = "ext-session-lock" },
    blur  = true,
    ignore_alpha = 0.2,
})

